glass.css:
:root {
  --bg-gradient: linear-gradient(135deg, #e0f2fe 0%, #chbeff 100%);
  --surface-bg: rgba(255, 255, 255, 0.45);
  --surface-border: rgba(255, 255, 255, 0.4);
  --text-primary: #1e293b;
  --text-secondary: #475569;
  --accent: #6366f1;
  --radius: 16px;
}
.glass {
  background: var(--surface-bg);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--surface-border);
  border-radius: var(--radius);
  padding: 24px;
  color: var(--text-primary);
  box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.08);
}
.glass h1 { font-size: 24px; color: var(--accent); margin-bottom: 12px; font-weight: 700; }
.glass p { font-size: 15px; color: var(--text-secondary); line-height: 1.6; }
.glass .btn {
  background: var(--accent); color: white; border: none; padding: 10px 20px;
  border-radius: 8px; cursor: pointer; transition: opacity 0.2s;
}
.glass .btn:hover { opacity: 0.9; }

frosted-dark.css:
:root {
  --bg-dark: #0f172a;
  --surface-bg: rgba(15, 23, 42, 0.6);
  --surface-border: rgba(255, 255, 255, 0.1);
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --accent: #38bdf8;
  --radius: 12px;
}
.frosted-dark {
  background: var(--surface-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--surface-border);
  border-radius: var(--radius);
  padding: 24px;
  color: var(--text-primary);
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
}
.frosted-dark h1 { font-size: 24px; color: var(--accent); margin-bottom: 12px; }
.frosted-dark p { font-size: 15px; color: var(--text-secondary); line-height: 1.6; }

elevated.css:
:root {
  --surface-bg: #ffffff;
  --text-primary: #18181b;
  --text-secondary: #71717a;
  --accent: #f43f5e;
  --radius: 12px;
  --shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
}
.elevated {
  background: var(--surface-bg);
  border-radius: var(--radius);
  padding: 28px;
  color: var(--text-primary);
  box-shadow: var(--shadow);
}
.elevated h1 { font-size: 26px; color: var(--accent); margin-bottom: 14px; font-weight: 800; }
.elevated p { font-size: 15px; color: var(--text-secondary); line-height: 1.6; }

bordered.css:
:root {
  --surface-bg: #ffffff;
  --text-primary: #000000;
  --text-secondary: #333333;
  --accent: #dc2626;
  --border-color: #000000;
}
.bordered {
  background: var(--surface-bg);
  border: 3px solid var(--border-color);
  border-radius: 4px;
  padding: 20px;
  color: var(--text-primary);
}
.bordered h1 { font-size: 22px; color: var(--accent); margin-bottom: 10px; font-weight: 900; text-transform: uppercase; }
.bordered p { font-size: 14px; color: var(--text-secondary); line-height: 1.5; font-weight: 700; }

flat.css:
:root {
  --surface-bg: #f4f4f5;
  --text-primary: #27272a;
  --text-secondary: #52525b;
  --accent: #0f766e;
}
.flat {
  background: var(--surface-bg);
  border-radius: 0px;
  padding: 24px;
  color: var(--text-primary);
}
.flat h1 { font-size: 24px; color: var(--accent); margin-bottom: 12px; font-weight: 500; }
.flat p { font-size: 15px; color: var(--text-secondary); line-height: 1.6; }

glow.css:
:root {
  --surface-bg: #05050a;
  --text-primary: #ffffff;
  --text-secondary: #a1a1aa;
  --accent: #00ffff;
  --glow-shadow: 0 0 15px rgba(0, 255, 255, 0.6);
}
.glow {
  background: var(--surface-bg);
  border: 1px solid var(--accent);
  border-radius: 8px;
  padding: 24px;
  color: var(--text-primary);
  box-shadow: var(--glow-shadow);
}
.glow h1 { font-size: 26px; color: var(--accent); text-shadow: var(--glow-shadow); margin-bottom: 12px; }
.glow p { font-size: 15px; color: var(--text-secondary); line-height: 1.6; }

neumorphism.css:
:root {
  --surface-bg: #e0e8f0;
  --text-primary: #4a5568;
  --text-secondary: #718096;
  --accent: #ed8936;
  --outer-shadow: 9px 9px 16px #be99cc, -9px -9px 16px #ffffff;
}
.neumorphism {
  background: var(--surface-bg);
  border-radius: 20px;
  padding: 30px;
  color: var(--text-primary);
  box-shadow: 9px 9px 16px #c8d0d9, -9px -9px 16px #f8ffff;
}
.neumorphism h1 { font-size: 24px; color: var(--accent); margin-bottom: 14px; }
.neumorphism p { font-size: 15px; color: var(--text-secondary); line-height: 1.6; }

paper.css:
:root {
  --surface-bg: #fcfaf2;
  --text-primary: #2c2520;
  --text-secondary: #5c5246;
  --accent: #8c2d19;
  --border-sepia: #e6dfd3;
}
.paper {
  background: var(--surface-bg);
  border: 1px solid var(--border-sepia);
  border-bottom: 2px solid #dcd5c5;
  border-radius: 2px;
  padding: 32px;
  color: var(--text-primary);
  font-family: 'Georgia', 'Times New Roman', 'Noto Serif JP', serif;
  box-shadow: 0 4px 6px rgba(0,0,0,0.05);
}
.paper h1 { font-size: 24px; color: var(--accent); margin-bottom: 16px; border-bottom: 1px solid var(--accent); padding-bottom: 6px; }
.paper p { font-size: 15px; color: var(--text-secondary); line-height: 1.7; letter-spacing: 0.05em; }
